import { CATEGORIES, STATUSES, STORAGE_KEY, localDate, readState, saveState, validateTask, withStatus, summarize, advanceDemo, escapeHTML as esc } from './state.js';
import { renderScene } from './scene.js';

const paths={
  grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V4h8v3M3 12q9 5 18 0M10 13h4"/>',
  sparkles:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v5m-2.5-2.5h5"/>',
  'check-square':'<rect x="3" y="3" width="18" height="18" rx="4"/><path d="m7 12 3.5 3.5L17 9"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',
  layers:'<path d="m12 3 10 5-10 5L2 8Zm-9 9 9 5 9-5M3 17l9 5 9-5"/>',
  pause:'<path d="M9 5v14M15 5v14"/>',play:'<path d="m8 4 12 8-12 8Z"/>',
  mouse:'<rect x="6" y="2" width="12" height="20" rx="6"/><path d="M12 6v4"/>',
  search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
  activity:'<path d="M2 12h4l3-8 6 16 3-8h4"/>',
  timer:'<circle cx="12" cy="14" r="8"/><path d="M12 10v5l3 2M9 2h6M12 2v4m6 2 2-2"/>',
  reset:'<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/>',
  help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 8a2.5 2.5 0 0 1 5 0c0 2-2.5 2-2.5 4m0 4h.01"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',
  close:'<path d="m6 6 12 12M6 18 18 6"/>',
  trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>'
};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.grid}</svg>`;
function hydrateIcons(root=document){root.querySelectorAll('i[data-icon]').forEach(el=>{el.outerHTML=icon(el.dataset.icon);});}
hydrateIcons();
const $=s=>document.querySelector(s);
let storage;
try { storage=window.localStorage; } catch {storage={getItem(){throw new Error('unavailable');},setItem(){throw new Error('unavailable');}}; }
let state=readState(storage);
let category='all',search='',zoom=1,demoRunning=false,demoInterval=null,motionPaused=matchMedia('(prefers-reduced-motion: reduce)').matches;
let toastTimeout,undoAction=null,persistenceFailed=false;
let timerRemaining=25*60,timerDeadline=null,timerInterval=null;

function toast(message,undo=null){clearTimeout(toastTimeout);undoAction=undo;const el=$('#toast');const suffix=persistenceFailed?' 변경 내용이 이 기기에 저장되지 않았어요.':'';el.innerHTML=`<span>${esc(message+suffix)}</span>${undo?'<button id="undo-action">되돌리기</button>':''}`;el.hidden=false;toastTimeout=setTimeout(()=>{el.hidden=true;undoAction=null;},undo?10000:5000);}
$('#toast').addEventListener('click',e=>{if(e.target.closest('#undo-action')&&undoAction){const action=undoAction;undoAction=null;action();$('#toast').hidden=true;}});
function addActivity(text){state.activities.unshift({id:crypto.randomUUID(),text,at:Date.now()});state.activities=state.activities.slice(0,15);}
function persist(){persistenceFailed=!saveState(storage,state);if(persistenceFailed)toast('현재 화면의 업무는 유지됩니다.');}
function commit(message){if(message)addActivity(message);persist();render();}
function dueLabel(due){if(!due)return '마감일 없음';const today=localDate();if(due===today)return '오늘';if(due<today)return '기한 지남';const [,m,d]=due.split('-');return `${Number(m)}월 ${Number(d)}일`;}
function currentTasks(){return state.tasks.filter(t=>(category==='all'||t.category===category)&&(!search||(t.title+' '+t.note).toLowerCase().includes(search.toLowerCase())));}
function renderMetrics(){const s=summarize(state.tasks);const cards=[['전체 업무',s.total,'개','grid','blue',''],['진행 중',s.doing,'개','clock','orange','차근차근 진행 중'],['AI 업무',s.ai,'개','sparkles','purple','완료 전 업무'],['완료한 업무',s.done,'개','check-square','green',s.total?Math.round(s.done/s.total*100)+'% 달성':'새롭게 시작해요']];$('#metrics').innerHTML=cards.map(([name,num,unit,i,color,meta])=>`<div class="metric-card"><div><div class="metric-name">${name}</div><div class="metric-value">${num}<small>${unit}</small><span class="metric-meta">${meta}</span></div></div><div class="metric-icon ${color}">${icon(i)}</div></div>`).join('');}
function renderBoard(){const tasks=currentTasks();$('#board-count').textContent=tasks.length;const cats=category==='all'?Object.keys(CATEGORIES):[category];$('#task-board').innerHTML=cats.map(c=>{const list=tasks.filter(t=>t.category===c);return `<section class="task-lane"><div class="lane-header"><span class="lane-title"><i class="dot ${c}"></i>${CATEGORIES[c]}<span class="lane-count">${list.length}</span></span><button class="lane-add" data-add-category="${c}" aria-label="${CATEGORIES[c]} 추가">+</button></div>${list.length?list.map(task=>`<button class="task-card ${task.status}" data-task-id="${esc(task.id)}" aria-label="${esc(task.title)}, ${STATUSES[task.status]}, 상세 보기"><div class="task-card-top"><span class="tag ${task.category}">${CATEGORIES[task.category]}</span>${task.priority==='high'?'<span class="priority-high">↑ 우선순위 높음</span>':''}</div><div class="task-card-title">${esc(task.title)}</div><div class="task-card-note">${esc(task.note)||'메모를 추가해 보세요'}</div>${task.category==='ai'&&task.status==='doing'?`<div class="task-mini-progress" role="progressbar" aria-label="${esc(task.title)} 데모 진행률" aria-valuenow="${task.progress}" aria-valuemin="0" aria-valuemax="100"><span style="width:${task.progress}%"></span></div>`:''}<div class="task-card-bottom"><span class="status-pill ${task.status}">${STATUSES[task.status]}</span><span>${dueLabel(task.due)}</span></div></button>`).join(''):'<p class="empty-lane">'+(search?'검색된 업무가 없어요.':'아직 업무가 없어요.<br>작은 일부터 시작해 보세요.')+'</p>'}</section>`;}).join('');}
function renderToday(){const todayTasks=state.tasks.filter(t=>t.due===localDate());const done=todayTasks.filter(t=>t.status==='done').length;$('#today-summary').textContent=`${todayTasks.length}개의 업무 중 ${done}개를 완료했어요`;$('#daily-progress-fill').style.width=todayTasks.length?`${done/todayTasks.length*100}%`:'0%';const list=[...todayTasks].sort((a,b)=>(a.status==='done')-(b.status==='done')||((b.priority==='high')-(a.priority==='high'))).slice(0,5);$('#today-list').innerHTML=list.length?list.map(t=>`<div class="today-row ${t.status}"><button class="task-checkbox ${t.status==='done'?'checked':''}" data-check-id="${esc(t.id)}" aria-label="${esc(t.title)} ${t.status==='done'?'완료 취소':'완료하기'}" aria-pressed="${t.status==='done'}">${t.status==='done'?icon('check'):''}</button><button class="today-task-button" data-task-id="${esc(t.id)}">${esc(t.title)}<small>${CATEGORIES[t.category]} <span>· ${STATUSES[t.status]}</span></small></button></div>`).join(''):'<p class="empty-lane">오늘 마감인 업무가 없어요.<br>여유롭게 다음 일을 준비해 보세요.</p>';}
function renderPartners(){const ai=state.tasks.filter(t=>t.category==='ai'&&t.status==='doing').slice(0,2);$('#ai-partners').innerHTML=ai.length?ai.map((t,i)=>`<div class="partner-row"><div class="partner-icon">${i?'✧':'✳'}</div><div class="partner-name">${esc(t.title)}<span>${demoRunning?'예시 작업 진행 중':'데모 대기 중'}</span></div><span class="partner-progress">${t.progress}%</span></div>`).join(''):'<div class="empty-lane">진행 중인 AI 업무가 없어요.</div>';const btn=$('#demo-toggle');btn.classList.toggle('is-running',demoRunning);btn.innerHTML=icon(demoRunning?'pause':'play')+`<span>${demoRunning?'AI 작업 데모 일시정지':'AI 작업 데모 시작'}</span>`;btn.disabled=!ai.length&&!demoRunning;}
function renderActivity(){$('#activity-list').innerHTML=state.activities.slice(0,3).map(a=>`<div class="activity-item"><span></span><span class="activity-text">${esc(a.text)}</span><time datetime="${new Date(a.at).toISOString()}">${new Date(a.at).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',hour12:false})}</time></div>`).join('');}
function render(){const active=document.activeElement;const activeId=active?.dataset.taskId;const activeClass=active?.classList.contains('task-card')?'.task-card':active?.classList.contains('scene-task-label')?'.scene-task-label':null;renderMetrics();renderBoard();renderToday();renderPartners();renderActivity();$('#workspace-scene').innerHTML=renderScene(state.tasks,category,demoRunning);applyZoom();applyMotion();const pending=state.tasks.filter(t=>t.status!=='done'&&(category==='all'||t.category===category)).length;$('#scene-caption').textContent=pending?`${category==='all'?'오늘의 공간':CATEGORIES[category]} · ${pending}개의 업무가 기다리고 있어요`:'모든 업무를 마쳤어요. 잠깐 쉬어가세요.';if(activeId&&activeClass){const match=[...document.querySelectorAll(activeClass)].find(el=>el.dataset.taskId===activeId);match?.focus({preventScroll:true});}}
function selectCategory(c){if(c!=='all'&&!Object.hasOwn(CATEGORIES,c))return;category=c;document.querySelectorAll('#navigation [data-category],#category-tabs [data-category]').forEach(el=>{const selected=el.dataset.category===c;el.classList.toggle('active',selected);el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected));});$('#breadcrumb-view').textContent=c==='all'?'오버뷰':CATEGORIES[c];render();}
function applyZoom(){const g=$('#scene-content');if(g)g.style.transform=`scale(${zoom})`;$('#zoom-reset').textContent=Math.round(zoom*100)+'%';$('#zoom-in').disabled=zoom>=1.4;$('#zoom-out').disabled=zoom<=.8;}
function applyMotion(){$('#scene-container').classList.toggle('motion-paused',motionPaused);const btn=$('#motion-toggle');btn.innerHTML=icon(motionPaused?'play':'pause');btn.setAttribute('aria-label',motionPaused?'공간 애니메이션 재생':'공간 애니메이션 일시정지');btn.title=btn.getAttribute('aria-label');btn.setAttribute('aria-pressed',String(motionPaused));}
function openTask(id=null,defaultCategory='personal'){const task=id?state.tasks.find(t=>t.id===id):null;if(id&&!task)return;const form=$('#task-form');form.reset();form.elements.id.value=task?.id||'';form.elements.title.value=task?.title||'';form.elements.category.value=task?.category||defaultCategory;form.elements.status.value=task?.status||'todo';form.elements.priority.value=task?.priority||'normal';form.elements.due.value=task?.due??localDate();form.elements.note.value=task?.note||'';$('#dialog-title').textContent=task?'업무 살펴보기':'새 업무 추가';$('#delete-task').hidden=!task;$('#task-dialog').showModal();$('#task-title').focus();}
function saveTask(input){const existing=input.id?state.tasks.find(t=>t.id===input.id):null;if(input.id&&!existing)throw new Error('업무를 찾을 수 없어요.');let task={id:existing?.id||crypto.randomUUID(),title:String(input.title||'').trim(),category:input.category,status:input.status,priority:input.priority,due:input.due||'',note:String(input.note||'').trim(),progress:existing?.progress||0};task=withStatus(task,task.status);if(!validateTask(task))throw new Error('업무 이름과 입력 내용을 확인해 주세요.');if(existing)state.tasks=state.tasks.map(t=>t.id===task.id?task:t);else state.tasks.unshift(task);commit(`${task.title} · ${existing?'업무 수정':'새 업무 추가'}${existing&&existing.status!==task.status?' · '+STATUSES[task.status]:''}`);return task;}
$('#task-form').addEventListener('submit',e=>{e.preventDefault();try{const task=saveTask(Object.fromEntries(new FormData(e.target)));$('#task-dialog').close();toast(`‘${task.title}’ 업무를 반영했어요.`);}catch(error){toast(error.message);}});
document.addEventListener('click',e=>{const close=e.target.closest('.close-dialog');if(close){close.closest('dialog').close();return;}const add=e.target.closest('[data-add-category]');if(add){openTask(null,add.dataset.addCategory);return;}const check=e.target.closest('[data-check-id]');if(check){const task=state.tasks.find(t=>t.id===check.dataset.checkId);if(!task)return;const previous={...task};state.tasks=state.tasks.map(t=>t.id===task.id?withStatus(t,t.status==='done'?'todo':'done'):t);commit(`${task.title} · ${task.status==='done'?'완료 취소':'완료했어요'}`);toast(task.status==='done'?'완료를 취소했어요.':'하나 더 해냈어요. 수고했어요!',()=>{state.tasks=state.tasks.map(t=>t.id===previous.id?previous:t);commit(`${previous.title} · 상태 변경 되돌리기`);});return;}const taskTarget=e.target.closest('[data-task-id]');if(taskTarget){openTask(taskTarget.dataset.taskId);return;}const categoryTarget=e.target.closest('[data-category]');if(categoryTarget)selectCategory(categoryTarget.dataset.category);});
$('#workspace-scene').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
$('#add-task').addEventListener('click',()=>openTask(null,category==='all'?'personal':category));$('#quick-add').addEventListener('click',()=>openTask(null,'todo'));
$('#delete-task').addEventListener('click',()=>{const id=$('#task-form').elements.id.value;const index=state.tasks.findIndex(t=>t.id===id);if(index<0)return;const deleted=state.tasks[index];state.tasks.splice(index,1);$('#task-dialog').close();commit(`${deleted.title} · 업무 삭제`);toast('업무를 삭제했어요.',()=>{state.tasks.splice(Math.min(index,state.tasks.length),0,deleted);commit(`${deleted.title} · 업무 복원`);});});
$('#help-button').addEventListener('click',()=>$('#help-dialog').showModal());
$('#task-search').addEventListener('input',e=>{search=e.target.value;renderBoard();});
$('#zoom-in').addEventListener('click',()=>{zoom=Math.min(1.4,Math.round((zoom+.1)*10)/10);applyZoom();});$('#zoom-out').addEventListener('click',()=>{zoom=Math.max(.8,Math.round((zoom-.1)*10)/10);applyZoom();});$('#zoom-reset').addEventListener('click',()=>{zoom=1;applyZoom();});
$('#motion-toggle').addEventListener('click',()=>{motionPaused=!motionPaused;applyMotion();});
function stopDemo(){demoRunning=false;clearInterval(demoInterval);demoInterval=null;}
$('#demo-toggle').addEventListener('click',()=>{if(demoRunning){stopDemo();commit('AI 작업 데모를 일시정지했어요.');return;}demoRunning=true;commit('AI 작업 데모를 시작했어요. 실제 AI 실행은 아닙니다.');demoInterval=setInterval(()=>{const before=state.tasks;state.tasks=advanceDemo(state.tasks);const completed=state.tasks.filter(t=>t.status==='review'&&before.find(p=>p.id===t.id)?.status==='doing');completed.forEach(t=>addActivity(`${t.title} · 데모 완료, 검토를 기다려요`));if(!state.tasks.some(t=>t.category==='ai'&&t.status==='doing'))stopDemo();persist();render();},2000);});
function renderTimer(){const seconds=timerDeadline?Math.max(0,Math.ceil((timerDeadline-Date.now())/1000)):timerRemaining;$('#timer-value').innerHTML=String(Math.floor(seconds/60)).padStart(2,'0')+'<span>:</span>'+String(seconds%60).padStart(2,'0');$('#timer-start').innerHTML=icon(timerDeadline?'pause':'play')+`<span>${timerDeadline?'잠깐 쉬기':timerRemaining===25*60?'집중 시작':'이어서 집중'}</span>`;$('#timer-description').textContent=timerDeadline?'좋아요. 지금은 나에게 집중하는 시간.':'지금, 한 가지 일에만 집중해 보세요.';if(timerDeadline&&seconds===0){timerDeadline=null;timerRemaining=25*60;clearInterval(timerInterval);timerInterval=null;commit('25분의 집중 시간을 완료했어요. 잠깐 쉬어가세요.');toast('25분 집중 완료! 잠깐 쉬어가세요.');renderTimer();}}
$('#timer-start').addEventListener('click',()=>{if(timerDeadline){timerRemaining=Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));timerDeadline=null;clearInterval(timerInterval);timerInterval=null;}else{timerDeadline=Date.now()+timerRemaining*1000;timerInterval=setInterval(renderTimer,250);}renderTimer();});
$('#timer-reset').addEventListener('click',()=>{clearInterval(timerInterval);timerInterval=null;timerDeadline=null;timerRemaining=25*60;renderTimer();toast('집중 시간을 25분으로 초기화했어요.');});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)renderTimer();});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY&&!$('#task-dialog').open){state=readState(storage);render();}});
$('#top-date').textContent=new Date().toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'long'});$('#day-badge').textContent=new Date().toLocaleDateString('en-US',{month:'short',day:'2-digit'}).toUpperCase();
render();if(state.warning)toast(state.warning);

// Optional WebMCP shares the visible UI's validated actions and state.
const modelContext=document.modelContext;
if(modelContext?.registerTool){
  const lifecycle=new AbortController();
  const tools=[
    {name:'list_workspace_tasks',description:'현재 브라우저의 Orbit 업무를 읽습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({tasks:state.tasks.map(t=>({...t}))})},
    {name:'create_workspace_task',description:'현재 브라우저에 업무를 추가하고 업무 공간과 보드에 반영합니다. 실제 AI를 실행하지 않습니다.',inputSchema:{type:'object',properties:{title:{type:'string',maxLength:80},category:{type:'string',enum:Object.keys(CATEGORIES)}},required:['title','category'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||typeof input.title!=='string'||!Object.hasOwn(CATEGORIES,input.category))throw new Error('업무 이름과 올바른 유형이 필요합니다.');const t=saveTask({title:input.title,category:input.category,status:'todo',priority:'normal',due:localDate(),note:''});return {id:t.id,title:t.title,status:t.status};}},
    {name:'update_workspace_task_status',description:'업무 상태를 변경하고 모든 화면에 반영합니다.',inputSchema:{type:'object',properties:{id:{type:'string'},status:{type:'string',enum:Object.keys(STATUSES)}},required:['id','status'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||typeof input.id!=='string'||!Object.hasOwn(STATUSES,input.status))throw new Error('올바른 업무 ID와 상태가 필요합니다.');const t=state.tasks.find(t=>t.id===input.id);if(!t)throw new Error('업무를 찾을 수 없습니다.');const saved=saveTask({...t,status:input.status});return {id:saved.id,status:saved.status};}}
  ];
  for(const tool of tools){try{Promise.resolve(modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{/* Optional browser capability; UI stays available. */}}
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
